<template><q-page class="page"><p class="eyebrow">ADMINISTRAÇÃO</p><h1 class="page-title">Revisar questões</h1><p class="copy">Revise classificação e envie várias questões para aprovação de uma vez.</p><q-banner v-if="error" rounded class="error">{{error}}</q-banner><q-inner-loading :showing="loading" color="primary"/><div v-if="questions.length" class="batch"><q-checkbox v-model="allSelected" label="Selecionar todas as questões em revisão"/><q-btn unelevated no-caps color="primary" icon="fact_check" :disable="!selectedIds.length" :loading="marking" :label="'Marcar para aprovação (' + selectedIds.length + ')'" @click="markSelected"/></div><q-list v-if="questions.length" bordered separator class="list"><q-expansion-item v-for="question in questions" :key="question.id"><template #header><q-item-section avatar><q-checkbox v-if="question.status==='REVIEW'" :model-value="selectedIds.includes(question.id)" @update:model-value="toggle(question.id, $event)" @click.stop/></q-item-section><q-item-section><q-item-label lines="2">{{question.statement}}</q-item-label><q-item-label caption>{{question.status==='REVIEW' ? 'Em revisão' : 'Aguardando aprovação'}} · {{question.board ?? 'Banca não identificada'}}</q-item-label></q-item-section></template><q-card flat><q-card-section><div class="question-header"><strong>{{ question.board ?? 'Banca não identificada' }}</strong><span>{{ contestLine(question) }}</span><span>{{ positionLine(question) }}</span></div><div v-if="question.assetUrls?.length" class="assets"><QuestionAssetImage v-for="url in question.assetUrls" :key="url" :url="url"/></div><div class="statement"><QuestionContent v-for="part in statementParts(question.statement)" :key="part" :value="part"/></div><div v-for="option in question.options" :key="option.id" class="option"><strong>{{option.label}}.</strong><QuestionContent :value="option.content"/><div v-if="option.assetUrls?.length" class="option-assets"><QuestionAssetImage v-for="url in option.assetUrls" :key="url" :url="url"/></div></div><q-select :options="subjectOptions" multiple emit-value map-options option-label="label" option-value="value" outlined label="Assuntos canônicos" v-model="selected[question.id]"/><div class="actions"><q-btn v-if="question.status==='DRAFT'" unelevated no-caps color="primary" label="Publicar questão" :loading="publishing===question.id" @click="publish(question.id)"/><q-btn flat no-caps color="primary" label="Salvar assuntos" :loading="savingTaxonomy===question.id" @click="assignTaxonomy(question.id,selected[question.id]??[])"/></div></q-card-section></q-card></q-expansion-item></q-list><q-card v-else-if="!loading" flat class="empty"><q-card-section>Nenhuma questão pendente de revisão.</q-card-section></q-card></q-page></template>
<script setup lang="ts">import{computed,onMounted,reactive,ref,watch}from'vue';import QuestionContent from '../QuestionBank/QuestionContent.vue';import QuestionAssetImage from '../QuestionBank/QuestionAssetImage.vue';import type{PublishedQuestion}from'../../../Domain/QuestionBank/QuestionRepository';import{useEditorial}from'./useEditorial';const{assignTaxonomy,error,load,loading,markForApproval,marking,publishing,publish,questions,savingTaxonomy,subjects}=useEditorial();const selected=reactive<Record<string,string[]>>({});const selectedIds=ref<string[]>([]);const subjectOptions=computed(()=>subjects.value.map(s=>({label:'· '.repeat(s.level)+s.name,value:s.id})));const reviewIds=computed(()=>questions.value.filter(q=>q.status==='REVIEW').map(q=>q.id));const allSelected=computed({get:()=>reviewIds.value.length>0&&reviewIds.value.every(id=>selectedIds.value.includes(id)),set:(value:boolean)=>{selectedIds.value=value?[...reviewIds.value]:[]}});watch(questions,(items)=>{for(const question of items)selected[question.id]=[...(question.taxonomySubjectIds??[])];selectedIds.value=selectedIds.value.filter(id=>items.some(question=>question.id===id&&question.status==='REVIEW'))},{immediate:true});function contestLine(question:PublishedQuestion):string{const p=(question.source??'').split('/').filter(Boolean);return (p.slice(0,2).join(' · ')||'Concurso não identificado')+(question.year?' · '+question.year:'')}function positionLine(question:PublishedQuestion):string{const p=(question.source??'').split('/').filter(Boolean);return p.slice(2).join(' · ')||'Cargo não identificado'}function statementParts(value:string):string[]{const normalized=value.replace(/\s+/g,' ').trim();const match=normalized.match(/^(.*?afirmativas? a seguir\.?)(.*)$/i);if(!match)return[normalized];const assertions=match[2].split(/(?=\s(?:I|II|III|IV|V|VI|VII|VIII|IX|X)\.)/).map(item=>item.trim()).filter(Boolean);return [match[1].trim(),...assertions]}function toggle(id:string,value:boolean){selectedIds.value=value?[...new Set([...selectedIds.value,id])]:selectedIds.value.filter(item=>item!==id)}async function markSelected(){await markForApproval(selectedIds.value);selectedIds.value=[]}onMounted(load);</script>
<style scoped>.page{max-width:1000px;margin:auto;padding:42px 34px}.eyebrow{color:#7187ad;font-size:11px;font-weight:800;letter-spacing:.1em}.page h1{color:#142950;margin:0}.copy{color:#71819e}.list,.empty,.batch{background:#fff;border:1px solid #e5ecf6;border-radius:16px;overflow:hidden}.batch{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:12px 16px;margin-bottom:16px}.error{margin:16px 0;background:#fff3f2;color:#ae2f25}.question-header{display:grid;gap:2px;padding:12px 14px;background:#eaf2ff;border-left:3px solid #1469e8;border-radius:10px;color:#153a78}.question-header strong{font-size:14px}.question-header span{font-size:12px}.assets{display:grid;gap:12px;margin:16px 0}.assets img{max-width:100%;max-height:520px;object-fit:contain;border:1px solid #dce6f4;border-radius:10px}.statement{margin:16px 0}.statement p{white-space:pre-line}.option{display:flex;gap:8px;padding:8px;background:#f6f8fc;border-radius:8px;margin:8px 0}.option :deep(.content){flex:1}.q-card p{padding:8px;background:#f6f8fc;border-radius:8px}.actions{display:flex;gap:8px;margin-top:12px}@media(max-width:600px){.page{padding:28px 16px}.batch{align-items:stretch;flex-direction:column}}
/* Revisão: mesa editorial, com lote destacado e conteúdo em largura confortável. */
.page{max-width:1080px!important}.page>h1{font-size:35px!important}.batch{position:sticky;top:12px;z-index:2;border:0!important;border-radius:18px!important;background:linear-gradient(100deg,#142d62,#1769f6)!important;color:#fff;box-shadow:0 12px 27px rgba(20,67,151,.20)}.batch .q-checkbox{color:#fff}.batch .q-btn{background:#fff!important;color:#1769f6!important}.list{border:0!important;border-radius:24px!important;background:transparent!important;overflow:visible!important}.list :deep(.q-expansion-item){margin:12px 0;border:1px solid #dce7f6;border-radius:18px;background:rgba(255,255,255,.82);overflow:hidden}.list :deep(.q-expansion-item--expanded){box-shadow:0 15px 34px rgba(37,71,126,.10)}.question-header{border-left-width:4px;border-radius:13px;background:linear-gradient(110deg,#e8f1ff,#f4f0ff)}.option{padding:13px 14px;border-radius:12px;background:#f5f8fd}.assets{padding:14px;border-radius:15px;background:#f8fbff}.empty{border-radius:22px!important;background:#f4f8ff!important}
</style>